import{_ as s,l as o,o as e,c as l,v as r,p as n,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"SR-IOV 与直通","description":"","frontmatter":{"title":"SR-IOV 与直通","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sriov-passthrough.md","filePath":"cs/sriov-passthrough.md","lastUpdated":1789023840000}'),c={name:"cs/sriov-passthrough.md"};function V(u,a,I,_,A,S){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="sr-iov-与直通" tabindex="-1">SR-IOV 与直通 <a class="header-anchor" href="#sr-iov-与直通" aria-label="Permalink to &quot;SR-IOV 与直通&quot;">​</a></h1><div class="epigraph"><p>SR-IOV 让一张物理网卡露出多个 VF：客户直接操作 VF 队列，几乎无 hypervisor 数据面；PF 仍由宿主管。</p><footer>—— 据 PCI-SIG SR-IOV；Linux 对 VF 的说明；[半虚拟](/cs/paravirtualization) 为对照</footer></div><p><a href="/cs/paravirtualization">virtio</a> 仍经宿主。<a href="/cs/dma-coherence">DMA</a> 要 IOMMU。缺口是 <strong>直通</strong>：VF 或整卡交给客户。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PF 出 VF，每个 VF 有自己的 BAR 与队列。客户跑原厂或 VF 驱动。缺口：迁移难（状态在卡上）；与 <a href="/cs/rss-multiqueue">RSS</a> 在 VF 内。本课不把每家网卡工具当文档。</p><p><span class="marginnote">GPU 直通同类但更重。对象是 PCI 功能级虚拟化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宿主启用 SR-IOV → VFIO 绑定 VF → QEMU dist 给客户。对照 virtio：可迁移、可快照更好。对照 <a href="/cs/dpdk-kernel-bypass">DPDK</a>：客户里可再旁路。对照 md RAID：无关。</p>',8)),(e(),n(h,null,{default:t(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E7%89%A9%E7%90%86%E5%8A%9F%E8%83%BD%20PF%22%5D%20--%3E%20VF%5B%22%E8%99%9A%E6%8B%9F%E5%8A%9F%E8%83%BD%22%5D%0A%20%20VF%20--%3E%20GUEST%5B%22%E5%AE%A2%E6%88%B7%E7%9B%B4%E6%8E%A5%20DMA%22%5D%0A%20%20IOMMU%5B%22IOMMU%22%5D%20--%3E%20ISO%5B%22%E9%9A%94%E7%A6%BB%20GPA%2FHPA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SR-IOV 把数据面还给硬件，换运维灵活性。IOMMU 是安全前提。不要写成网卡广告。与 <a href="/cs/netns-veth">netns</a>：VF 可进宿主 ns 或直通，二选路径。</p><p>没有 IOMMU 的直通等于客户可 DMA 宿主。</p><p>实现上：VF 的 MAC/VLAN 由 PF 上的宿主策略管。迁移要热拔 VF 再在对端插，状态难搬。没有 ACS 的桥可能让 DMA 隔离失败。 读法上只引用<a href="/cs/paravirtualization">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>SR-IOV 与直通</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 ACS 桥问题。不保证无线 SR-IOV。下一课用户态安全直通框架：VFIO。</p><p>版本字段会变，课序钉的是机制对象「SR-IOV 与直通」，不是某一主线内核的结构体名。 后课默认：VF 可直通给客户。VFIO 如何绑 IOMMU 组，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SR-IOV 提供 VF 供客户直通。</li><li>快，但迁移与共享策略变难。</li><li>VFIO 是下一课。</li><li>出处：PCI SR-IOV；Linux networking；VFIO。</li></ul>',11))])}const O=s(c,[["render",V]]);export{m as __pageData,O as default};
